const s = params.height / 1.75;
const cloth = { preset: 'fabric', color: params.khaki, roughness: 0.9 };
const oliveM = { preset: 'fabric', color: params.olive, roughness: 0.9 };
const skinM = { preset: 'plastic', color: params.skin, roughness: 0.6 };
const scarfM = { preset: 'fabric', color: params.scarf, roughness: 0.85 };
const bootM = { preset: 'rubber', color: params.boots, roughness: 0.8 };
const dark = { preset: 'plastic', color: '#1d1d1d', roughness: 0.4 };
const add = (m, mat) => { api.add(m.scale(s), mat); };
for (const sx of [-1, 1]) {
  add(api.box(0.17, 0.12, 0.22).translate(sx * 0.09, 0.07, 0.0), bootM);
  add(api.sphere(0.085, 2).scale(1, 0.75, 1).translate(sx * 0.09, 0.065, 0.12), bootM);
  add(api.cylinder(0.08, 0.085, 0.16, 12).translate(sx * 0.09, 0.2, -0.01), bootM);
  add(api.cylinder(0.072, 0.07, 0.6, 14).translate(sx * 0.09, 0.5, 0), cloth);
  add(api.cylinder(0.078, 0.078, 0.04, 14).translate(sx * 0.09, 0.3, 0), oliveM);
  // arm
  const arm = api.capsule(0.045, 0.45).translate(0, -0.225, 0).rotate(0, 0, sx * 18).translate(sx * 0.2, 1.22, 0);
  add(arm, cloth);
  add(api.sphere(0.065, 2).translate(sx * 0.2, 1.22, 0), cloth);
  const ex = sx * (0.2 + 0.4 * Math.sin(18 * Math.PI / 180));
  const ey = 1.22 - 0.4 * Math.cos(18 * Math.PI / 180);
  add(api.cylinder(0.052, 0.052, 0.05, 12).translate(0, -0.03, 0).rotate(0, 0, sx * 18).translate(ex, ey, 0), oliveM);
  const hx = sx * (0.2 + 0.49 * Math.sin(18 * Math.PI / 180));
  const hy = 1.22 - 0.49 * Math.cos(18 * Math.PI / 180);
  add(api.sphere(0.06, 2).translate(hx, hy, 0), skinM);
  // eyes
  add(api.sphere(0.03, 2).scale(1, 1.3, 0.5).translate(sx * 0.08, 1.5, 0.215), dark);
  // vest pockets
  add(api.box(0.09, 0.09, 0.03).translate(sx * 0.09, 0.95, 0.13), cloth);
}
// pelvis + torso
add(api.sphere(1, 3).scale(0.19, 0.12, 0.12).translate(0, 0.84, 0), cloth);
add(api.sphere(1, 3).scale(0.19, 0.25, 0.12).translate(0, 1.04, 0), cloth);
add(api.sphere(1, 3).scale(0.2, 0.2, 0.13).translate(0, 1.02, 0.005), oliveM);
add(api.cylinder(0.185, 0.19, 0.05, 16).scale(1, 1, 0.68).translate(0, 0.86, 0), oliveM);
add(api.box(0.04, 0.4, 0.01).translate(0, 1.02, 0.132), cloth);
// scarf
add(api.torus(0.14, 0.05).rotate(90, 0, 0).translate(0, 1.3, 0), scarfM);
add(api.box(0.08, 0.26, 0.04).translate(0.1, 1.15, 0.14).rotate(0, 0, 4), scarfM);
// head
add(api.sphere(0.23, 4).translate(0, 1.47, 0), skinM);
add(api.sphere(0.04, 2).translate(0, 1.44, 0.23), skinM);
// hat
add(api.cylinder(0.19, 0.22, 0.12, 18).translate(0, 1.7, 0), cloth);
add(api.sphere(0.19, 3).scale(1, 0.4, 1).translate(0, 1.76, 0), cloth);
add(api.cylinder(0.38, 0.4, 0.02, 28).rotate(3, 0, 0).translate(0, 1.64, 0), cloth);
add(api.cylinder(0.215, 0.222, 0.04, 18).translate(0, 1.67, 0), oliveM);
// backpack
add(api.box(0.3, 0.42, 0.16).translate(0, 1.04, -0.2), oliveM);
add(api.box(0.24, 0.12, 0.04).translate(0, 0.95, -0.29), cloth);
for (const sx of [-1, 1]) add(api.box(0.04, 0.38, 0.02).translate(sx * 0.1, 1.08, 0.0).translate(0, 0, 0.115), oliveM);
add(api.cylinder(0.07, 0.07, 0.42, 14).rotate(0, 0, 90).translate(0, 1.3, -0.2), cloth);
for (const sx of [-1, 1]) add(api.cylinder(0.072, 0.072, 0.02, 14).rotate(0, 0, 90).translate(sx * 0.15, 1.3, -0.2), oliveM);
api.collider({ kind: 'capsule', halfHeight: 0.4 * s, radius: 0.2 * s, offset: [0, 0.95 * s, -0.04 * s] });
api.collider({ kind: 'box', halfExtents: [0.15 * s, 0.4 * s, 0.1 * s], offset: [0, 0.4 * s, 0] });
api.collider({ kind: 'cylinder', halfHeight: 0.04 * s, radius: 0.38 * s, offset: [0, 1.65 * s, 0] });
api.collider({ kind: 'sphere', radius: 0.23 * s, offset: [0, 1.5 * s, 0] });
return api.build();
